    'The Discovery of India': 'भारताचा शोध',
    'The admission form has been moved to a separate page so families can complete it without leaving the full homepage experience.':
        'प्रवेश फॉर्म वेगळ्या पृष्ठावर हलविला गेला आहे जेणेकरून कुटुंबे संपूर्ण मुख्यपृष्ठाचा अनुभव न सोडता ते पूर्ण करू शकतील.',
    'The admission form is now available on a separate page, which makes the homepage lighter and gives families a focused application flow.':
        'प्रवेश फॉर्म आता स्वतंत्र पृष्ठावर उपलब्ध आहे, जे मुख्यपृष्ठ हलके करते आणि कुटुंबांना एक केंद्रित अनुप्रयोग प्रवाह देते.',
    'The fee counter will remain open until 4:30 PM for the quarterly payment cycle.':
        'तिमाही पेमेंट सायकलसाठी फी काउंटर दुपारी 4:30 वाजेपर्यंत खुले राहील.',
    'The form now lives on a dedicated admissions page for a cleaner public homepage and a more focused enquiry experience.':
        'हा फॉर्म आता स्वच्छ सार्वजनिक मुख्यपृष्ठ आणि अधिक केंद्रित चौकशी अनुभवासाठी समर्पित प्रवेश पृष्ठावर राहतो.',
    'The page keeps polling the bridge and will update automatically after the QR is scanned.':
        'पृष्ठ पुलावर मतदान करत राहते आणि क्यूआर स्कॅन केल्यानंतर स्वयंचलितपणे अद्यतनित होईल.',
    'The requested student record could not be loaded.': 'विनंती केलेले विद्यार्थी रेकॉर्ड लोड केले जाऊ शकले नाही.',
    'The status refreshes automatically every few seconds while connecting.':
        'कनेक्ट करताना दर काही सेकंदांनी स्थिती स्वयंचलितपणे रीफ्रेश होते.',
    'Theory + Practical': 'सिद्धांत + व्यावहारिक',
    'These images can be reused by the homepage templates.':
        'या प्रतिमा होमपेज टेम्पलेटद्वारे पुनर्संचयित केल्या जाऊ शकतात.',
    'These rows will be skipped:': 'या रेषा वगळले जातीलः',
